import type { Lang } from "../i18n/ui-locales";

export interface HelpPageCopy {
    title: string;
    description: string;
    eyebrow: string;
    intro: string;
    startTitle: string;
    startBody: string;
    guidesTitle: string;
    guides: { title: string; body: string }[];
    limitsTitle: string;
    limits: string[];
    faqTitle: string;
    faq: { q: string; a: string }[];
    linksTitle: string;
    links: { privacy: string; disclaimer: string; subscription: string; support: string };
    updated: string;
}

type HelpPageDraft = Omit<HelpPageCopy, "guides" | "faq" | "links"> & {
    guides: [string, string][];
    faq: [string, string][];
    links: [string, string, string, string];
};

const makePage = (draft: HelpPageDraft): HelpPageCopy => {
    const { guides, faq, links, ...copy } = draft;
    return {
        ...copy,
        guides: guides.map(([title, body]) => ({ title, body })),
        faq: faq.map(([q, a]) => ({ q, a })),
        links: { privacy: links[0], disclaimer: links[1], subscription: links[2], support: links[3] },
    };
};

